-- DQ-009: Histology and ER Status Consistency---- Purpose:-- Validate the distribution of ER.Status within each-- histological subtype in the staging layer.---- This validation checks whether the cross-tabulation-- preserves the complete staging population.---- Expected total:-- - 705 records---- This validation does not modify the data.SELECT    "histological.type",    "ER.Status",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY    "histological.type",    "ER.Status"ORDER BY    "histological.type",    quantity DESC;